using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using FileFormat.Core;
using FileFormat.H264Video;

namespace FileFormat.Codecs.H264.Tests;

[TestFixture]
public sealed class H264CabacHighProfileConformanceTests {
  private static readonly MediaStreamInfo _AnnexBStream = new() {
    Index = 0,
    Kind = MediaStreamKind.Video,
    Codec = CodecTag.FromCharacters("avc1"),
  };

  // x264 core 164, High profile, progressive 8-bit 4:2:0, 64x64, QP 20,
  // CABAC, three references, two B frames, spatial+temporal direct and 8x8 transform enabled.
  // x264 reported 10.8% inter 8x8-transform use for this stream. FFmpeg 7.1.5 produced
  // the native YUV420 oracle hashes below in presentation order.
  private const string _CABAC_HIGH_8X8_IPBB =
    "";

  [Test]
  public void HighProfileCabac8x8IPBBMatchesReferenceDecoderExactly() {
    var frames = _Decode(Convert.FromBase64String(_CABAC_HIGH_8X8_IPBB));
    Assert.That(frames, Has.Count.EqualTo(4));
    string[] expected = [
      "0755CED4589D10710451D02DB9243401AE1AE3BDA942FE5E402216C4DE674A1C",
      "AB6FE4836A41C22F400029C8A9397D6ED205F41D074C5F87F266E55AD0ECFE2E",
      "F027940455299FF34166AAD28B17BAF8F0C59B1A38F806367AA0804519B5471B",
      "A06212014520FBF827E38099004AAF6524248895BC9708F884C4EE8185319CB4",
    ];

    for (var index = 0; index < frames.Count; ++index) {
      Assert.That(frames[index].Format, Is.EqualTo(PixelFormat.Yuv420P8), $"frame {index}");
      Assert.That(frames[index].Width, Is.EqualTo(64), $"frame {index}");
      Assert.That(frames[index].Height, Is.EqualTo(64), $"frame {index}");
      Assert.That(Convert.ToHexString(SHA256.HashData(frames[index].PixelData)), Is.EqualTo(expected[index]), $"frame {index}");
    }
  }

  private static List<RawImage> _Decode(byte[] stream) {
    var decoder = H264VideoDecoder.Create(_AnnexBStream);
    var frames = new List<RawImage>();
    foreach (var packet in H264VideoReader.Split(stream))
      if (decoder.TryDecode(packet, out var frame))
        frames.Add(frame);
    frames.AddRange(decoder.Flush());
    return frames;
  }
}
